bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,
 database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
try{
 const q=await pool.query("SELECT s.state->>'publishing' AS publishing FROM videobot_creator_sessions s JOIN videobot_listings l ON l.seller_user_id=s.owner_user_id WHERE l.listing_id=$1",['v26nov24invoice']);
 if(q.rows.length!==1)process.exit(61);
 const status=q.rows[0].publishing;
 if(status==='needs_reconcile')process.exit(71);
 if(status==='in_progress')process.exit(72);
 console.log('VIDEO_OWNER_NEW_REGISTRATION_SESSION_NOT_LOCKED=PASS');
}finally{await pool.end()}
JS
